const crm2OportunidadesState = {
  canView: false, canCreate: false, canEdit: false, canDelete: false,
  leads: structuredClone(CRM2_OPPORTUNITY_LEADS),
  opportunities: structuredClone(CRM2_OPPORTUNITY_ITEMS),
  section: 'opportunities', viewMode: 'table', search: '', stageFilter: '', statusFilter: '', responsibleFilter: '', sourceFilter: '', lossReasonFilter: '', dateFrom: '', dateTo: '', page: 1, perPage: 6, listState: 'normal', detailId: '', detailTab: 'dados', formMode: '', draft: {}, errors: {}, duplicateQuery: '', duplicateMatches: [], duplicateChecked: false, allowDuplicate: false, message: ''
};

crm2OportunidadesState.conversion = { open: false, mode: 'total', selectedItemIds: [], pfId: '', pjId: '', vinculoTipo: 'Representante legal', responsavel: 'Ana Martins', observacoes: '', errors: {}, result: null };

function escapeOpp(value = '') { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;'); }
function attrOpp(value = '') { return escapeOpp(value).replaceAll('`', '&#096;'); }
function normOpp(value = '') { return String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim(); }
function digitsOpp(value = '') { return String(value ?? '').replace(/\D/g, ''); }
function dateOpp(value = '') { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short' }).format(d); }
function dateTimeOpp(value = '') { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(d); }
function moneyOpp(value = '') { return `R$ ${escapeOpp(value || '0,00')}`; }
function permissionsOpp() { const permissions = obterContextoAcessoHub()?.permissions || {}; const resolve = (action) => hasPermission(permissions, 'painel_ar', action); crm2OportunidadesState.canView = resolve('view'); crm2OportunidadesState.canCreate = resolve('create') || resolve('update'); crm2OportunidadesState.canEdit = resolve('update'); crm2OportunidadesState.canDelete = resolve('delete'); }
function currentOppRoute() { const parts = window.location.pathname.split('/').filter(Boolean); const index = parts.findIndex((part, position) => part === 'painel-ar' && parts[position + 1] === '205'); if (index < 0) return { active: false, view: 'list', id: '' }; const tail = parts.slice(index + 2); if (tail[0] === 'lead' && tail[1] === 'novo') return { active: true, view: 'lead-new', id: '' }; if (tail[0] === 'oportunidade' && tail[1] === 'novo') return { active: true, view: 'opp-new', id: '' }; if (tail[0] === 'oportunidade' && tail[2] === 'editar') return { active: true, view: 'opp-edit', id: tail[1] || '' }; if (tail[0] === 'oportunidade' && tail[1]) return { active: true, view: 'opp-detail', id: tail[1] }; return { active: true, view: 'list', id: '' }; }
function oppPath(suffix = '') { const hasHub = window.location.pathname.split('/').filter(Boolean)[0] === 'hub'; return `${hasHub ? '/hub' : ''}/painel-ar/205${suffix ? `/${suffix}` : ''}`; }
function navigateOpp(suffix = '') { window.history.pushState({}, '', oppPath(suffix)); window.dispatchEvent(new PopStateEvent('popstate')); window.setTimeout(() => window.crm2OportunidadesMount?.(), 0); }
function leadById(id) { return crm2OportunidadesState.leads.find((lead) => lead.id === id) || null; }
function opportunityById(id) { return crm2OportunidadesState.opportunities.find((opp) => opp.id === id) || null; }
function relatedPfOpp(id) { const records = window.crm2PfGetMockItems?.() || []; return records.find((item) => item.id === id) || null; }
function relatedPjOpp(id) { const records = window.crm2PjGetMockItems?.() || []; return records.find((item) => item.id === id) || null; }
function leadLabel(lead) { return lead ? (lead.tipo === 'PJ' ? lead.razaoSocial : lead.nome) : 'Lead provisório'; }
function opportunityLabel(opp) { const lead = leadById(opp.leadId); const pf = relatedPfOpp(opp.pfId); const pj = relatedPjOpp(opp.pjId); return leadLabel(lead) !== 'Lead provisório' ? leadLabel(lead) : pf?.nome || pj?.razaoSocial || 'Registro relacionado'; }
function totalOpp(opp) { return (opp.itens || []).reduce((total, item) => total + (Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.'))), 0); }
function statusClassOpp(value = '') { return normOpp(value).replace(/\s+/g, '-'); }
function stagePillOpp(value) { return `<span class="crm2-opp-pill is-${attrOpp(statusClassOpp(value))}">${escapeOpp(value)}</span>`; }

function filteredOpps() { const search = normOpp(crm2OportunidadesState.search); return crm2OportunidadesState.opportunities.filter((opp) => { const values = [opp.numero, opp.titulo, opportunityLabel(opp), opp.responsavel, opp.etapa, opp.status, opp.origem, opp.motivoPerda].map(normOpp); return (!search || values.some((value) => value.includes(search))) && (!crm2OportunidadesState.stageFilter || opp.etapa === crm2OportunidadesState.stageFilter) && (!crm2OportunidadesState.statusFilter || opp.status === crm2OportunidadesState.statusFilter) && (!crm2OportunidadesState.responsibleFilter || opp.responsavel === crm2OportunidadesState.responsibleFilter) && (!crm2OportunidadesState.sourceFilter || opp.origem === crm2OportunidadesState.sourceFilter) && (!crm2OportunidadesState.lossReasonFilter || opp.motivoPerda === crm2OportunidadesState.lossReasonFilter) && (!crm2OportunidadesState.dateFrom || String(opp.criadoEm).slice(0, 10) >= crm2OportunidadesState.dateFrom) && (!crm2OportunidadesState.dateTo || String(opp.criadoEm).slice(0, 10) <= crm2OportunidadesState.dateTo); }); }
function duplicateMatchesOpp(query = '') { const q = normOpp(query); const digits = digitsOpp(query); if (!q && !digits) return []; const pf = (window.crm2PfGetMockItems?.() || []).filter((item) => [item.nome, item.cpf, item.email].some((value) => normOpp(value).includes(q) || (digits && digitsOpp(value).includes(digits)))).map((item) => ({ ...item, origemRegistro: 'Pessoa Física' })); const pj = (window.crm2PjGetMockItems?.() || []).filter((item) => [item.razaoSocial, item.cnpj].some((value) => normOpp(value).includes(q) || (digits && digitsOpp(value).includes(digits)))).map((item) => ({ ...item, origemRegistro: 'Pessoa Jurídica' })); const leads = crm2OportunidadesState.leads.filter((item) => [item.nome, item.razaoSocial, item.cpf, item.cnpj, item.email].some((value) => normOpp(value).includes(q) || (digits && digitsOpp(value).includes(digits)))).map((item) => ({ ...item, origemRegistro: 'Lead provisório' })); return [...pf, ...pj, ...leads].slice(0, 8); }
function formDefaultsOpp(opp = {}) { return { titulo: opp.titulo || '', leadId: opp.leadId || '', pfId: opp.pfId || '', pjId: opp.pjId || '', status: opp.status || 'Aberta', etapa: opp.etapa || 'Novo', responsavel: opp.responsavel || 'Ana Martins', origem: opp.origem || 'Atendimento interno', probabilidade: String(opp.probabilidade ?? 10), previsaoFechamento: opp.previsaoFechamento || '', motivoPerda: opp.motivoPerda || '', observacoes: opp.observacoes || '', itens: Array.isArray(opp.itens) && opp.itens.length ? opp.itens.map((item) => ({ ...item })) : [{ id: `item-${Date.now()}`, produto: '', quantidade: 1, valorUnitario: '' }] }; }
function resetOppForm() { crm2OportunidadesState.formMode = ''; crm2OportunidadesState.detailId = ''; crm2OportunidadesState.draft = {}; crm2OportunidadesState.errors = {}; }

function renderOppState() { const copy = { loading: ['Carregando oportunidades...', 'Estado simulado para homologação.'], error: ['Não foi possível carregar oportunidades.', 'Erro simulado. Nenhuma integração externa foi acionada.'], empty: ['Nenhuma oportunidade cadastrada.', 'A lista mockada ainda não possui negociações.'] }[crm2OportunidadesState.listState]; if (!copy) return ''; return `<div class="crm2-pessoas-state crm2-opp-state ${crm2OportunidadesState.listState === 'error' ? 'is-error' : ''}" role="${crm2OportunidadesState.listState === 'error' ? 'alert' : 'status'}"><strong>${copy[0]}</strong><span>${copy[1]}</span><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetState('normal')">Voltar à lista</button></div>`; }
function renderOppFilters() { const active = Boolean(crm2OportunidadesState.search || crm2OportunidadesState.stageFilter || crm2OportunidadesState.statusFilter || crm2OportunidadesState.responsibleFilter || crm2OportunidadesState.sourceFilter || crm2OportunidadesState.lossReasonFilter || crm2OportunidadesState.dateFrom || crm2OportunidadesState.dateTo); const responsibles = [...new Set(crm2OportunidadesState.opportunities.map((opp) => opp.responsavel))]; return `<form class="crm2-opp-filters" role="search" onsubmit="crm2OportunidadesApplyFilters(event)" aria-label="Filtrar oportunidades"><label><span>Buscar</span><input class="config-input" name="search" type="search" value="${attrOpp(crm2OportunidadesState.search)}" placeholder="Número, título, lead ou responsável"></label><label><span>Etapa</span><select class="config-input" name="stage"><option value="">Todas as etapas</option>${OPPORTUNITY_STAGES.map((item) => `<option value="${attrOpp(item)}" ${crm2OportunidadesState.stageFilter === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}</select></label><label><span>Status</span><select class="config-input" name="status"><option value="">Todos os status</option>${OPPORTUNITY_STATUSES.map((item) => `<option value="${attrOpp(item)}" ${crm2OportunidadesState.statusFilter === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}</select></label><label><span>Responsável</span><select class="config-input" name="responsible"><option value="">Todos</option>${responsibles.map((item) => `<option value="${attrOpp(item)}" ${crm2OportunidadesState.responsibleFilter === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}</select></label><label><span>Origem</span><select class="config-input" name="source"><option value="">Todas</option>${OPPORTUNITY_SOURCES.map((item) => `<option value="${attrOpp(item)}" ${crm2OportunidadesState.sourceFilter === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}</select></label><label><span>Motivo de perda</span><select class="config-input" name="lossReason"><option value="">Todos</option>${OPPORTUNITY_LOSS_REASONS.map((item) => `<option value="${attrOpp(item)}" ${crm2OportunidadesState.lossReasonFilter === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}</select></label><label><span>Criada desde</span><input class="config-input" name="dateFrom" type="date" value="${attrOpp(crm2OportunidadesState.dateFrom)}"></label><label><span>Criada até</span><input class="config-input" name="dateTo" type="date" value="${attrOpp(crm2OportunidadesState.dateTo)}"></label><div class="crm2-opp-filter-actions"><button class="save-btn" type="submit">Aplicar filtros</button><button class="secondary-btn" type="button" onclick="crm2OportunidadesClearFilters()" ${active ? '' : 'disabled'}>Limpar</button></div></form>`; }
function renderOppTable(items) { return `<div class="ar-crm-phase1-table-wrap crm2-opp-table-wrap"><table class="ar-crm-phase1-table crm2-opp-table"><caption class="crm2-pessoas-table-caption">Oportunidades do CRM 2.0</caption><thead><tr><th>Oportunidade</th><th>Lead/cliente</th><th>Etapa</th><th>Responsável</th><th>Valor</th><th>Fechamento</th><th>Ações</th></tr></thead><tbody>${items.map((opp) => `<tr><td><button class="crm2-opp-link" type="button" onclick="crm2OportunidadesOpenDetail('${attrOpp(opp.id)}')">${escapeOpp(opp.numero)}</button><small>${escapeOpp(opp.titulo)}</small></td><td>${escapeOpp(opportunityLabel(opp))}<small>${escapeOpp(opp.origem)}</small></td><td>${stagePillOpp(opp.etapa)}<small>${escapeOpp(opp.status)}</small></td><td>${escapeOpp(opp.responsavel)}</td><td>${moneyOpp(opp.valorEstimado || totalOpp(opp))}<small>${(opp.itens || []).length} item(ns)</small></td><td>${escapeOpp(dateOpp(opp.previsaoFechamento))}</td><td><button class="secondary-btn" type="button" onclick="crm2OportunidadesOpenDetail('${attrOpp(opp.id)}')">Visualizar</button>${crm2OportunidadesState.canEdit ? `<button class="secondary-btn" type="button" onclick="crm2OportunidadesOpenEdit('${attrOpp(opp.id)}')">Editar</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`; }
function renderOppKanban(items) { return `<div class="crm2-opp-kanban">${OPPORTUNITY_STAGES.map((stage) => { const stageItems = items.filter((opp) => opp.etapa === stage); return `<section class="crm2-opp-kanban-column" aria-labelledby="crm2-opp-stage-${statusClassOpp(stage)}"><header><strong id="crm2-opp-stage-${statusClassOpp(stage)}">${escapeOpp(stage)}</strong><span>${stageItems.length}</span></header><div>${stageItems.length ? stageItems.map((opp) => `<article class="crm2-opp-card"><button class="crm2-opp-link" type="button" onclick="crm2OportunidadesOpenDetail('${attrOpp(opp.id)}')">${escapeOpp(opp.numero)}</button><strong>${escapeOpp(opp.titulo)}</strong><span>${escapeOpp(opportunityLabel(opp))}</span><small>${moneyOpp(opp.valorEstimado || totalOpp(opp))} · ${escapeOpp(opp.responsavel)}</small></article>`).join('') : '<p class="crm2-opp-kanban-empty">Nenhum registro</p>'}</div></section>`; }).join('')}</div>`; }
function renderLeadList() { return `<div class="crm2-opp-leads"><div class="crm2-opp-leads-header"><div><strong>Leads e cadastros provisórios</strong><span>Registros comerciais ainda não convertidos.</span></div>${crm2OportunidadesState.canCreate ? '<button class="save-btn" type="button" onclick="crm2OportunidadesOpenLeadCreate()">+ Novo lead</button>' : ''}</div><div class="ar-crm-phase1-table-wrap crm2-opp-table-wrap"><table class="ar-crm-phase1-table crm2-opp-table"><thead><tr><th>Identificação</th><th>Tipo</th><th>Origem</th><th>Status</th><th>Responsável</th><th>Atualizado</th></tr></thead><tbody>${crm2OportunidadesState.leads.map((lead) => `<tr><td><strong>${escapeOpp(leadLabel(lead))}</strong><small>${escapeOpp(lead.cpf || lead.cnpj || lead.email || 'Identificação provisória')}</small></td><td>${escapeOpp(lead.tipo)}</td><td>${escapeOpp(lead.origem)}</td><td>${stagePillOpp(lead.status)}</td><td>${escapeOpp(lead.responsavel)}</td><td>${escapeOpp(dateTimeOpp(lead.atualizadoEm))}</td></tr>`).join('')}</tbody></table></div></div>`; }
function renderOppList() { const filtered = filteredOpps(); const totalPages = Math.max(1, Math.ceil(filtered.length / crm2OportunidadesState.perPage)); crm2OportunidadesState.page = Math.min(Math.max(1, crm2OportunidadesState.page), totalPages); const pageItems = filtered.slice((crm2OportunidadesState.page - 1) * crm2OportunidadesState.perPage, crm2OportunidadesState.page * crm2OportunidadesState.perPage); const content = crm2OportunidadesState.listState !== 'normal' ? renderOppState() : pageItems.length ? (crm2OportunidadesState.viewMode === 'kanban' ? renderOppKanban(filtered) : `${renderOppTable(pageItems)}<div class="crm2-opp-pagination"><span>Página <strong>${crm2OportunidadesState.page}</strong> de <strong>${totalPages}</strong> · ${filtered.length} oportunidade(s)</span><div><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetPage(${crm2OportunidadesState.page - 1})" ${crm2OportunidadesState.page <= 1 ? 'disabled' : ''}>Anterior</button><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetPage(${crm2OportunidadesState.page + 1})" ${crm2OportunidadesState.page >= totalPages ? 'disabled' : ''}>Próxima</button></div></div>`) : `<div class="crm2-pessoas-state" role="status"><strong>${crm2OportunidadesState.opportunities.length ? 'Nenhum resultado encontrado.' : 'Nenhuma oportunidade cadastrada.'}</strong><span>Ajuste os filtros ou cadastre uma nova oportunidade.</span><button class="secondary-btn" type="button" onclick="crm2OportunidadesClearFilters()">Limpar filtros</button></div>`; return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-opp-title"><div class="admin-panel-header crm2-pessoas-list-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · CRM 2.0</span><h3 id="crm2-opp-title">Oportunidades</h3><p class="crm2-opp-subtitle">Gestão mockada de leads, negociações e itens comerciais.</p></div><div class="crm2-pessoas-header-actions"><button class="secondary-btn" type="button" onclick="navegarParaCrm2Rota('200')">Voltar ao CRM 2.0</button>${crm2OportunidadesState.canCreate ? '<button class="save-btn" type="button" onclick="crm2OportunidadesOpenCreate()">+ Oportunidade</button>' : ''}</div></div><div class="crm2-opp-section-tabs" role="tablist" aria-label="Seção comercial"><button class="${crm2OportunidadesState.section === 'opportunities' ? 'active' : ''}" type="button" role="tab" aria-selected="${crm2OportunidadesState.section === 'opportunities'}" onclick="crm2OportunidadesSetSection('opportunities')">Oportunidades</button><button class="${crm2OportunidadesState.section === 'leads' ? 'active' : ''}" type="button" role="tab" aria-selected="${crm2OportunidadesState.section === 'leads'}" onclick="crm2OportunidadesSetSection('leads')">Leads</button></div>${crm2OportunidadesState.section === 'leads' ? renderLeadList() : `${renderOppFilters()}<div class="crm2-opp-view-toggle"><span>${filtered.length} oportunidade(s)</span><button class="secondary-btn ${crm2OportunidadesState.viewMode === 'table' ? 'active' : ''}" type="button" onclick="crm2OportunidadesSetView('table')">Tabela</button><button class="secondary-btn ${crm2OportunidadesState.viewMode === 'kanban' ? 'active' : ''}" type="button" onclick="crm2OportunidadesSetView('kanban')">Kanban</button></div>${content}`}</section>`; }

function renderLeadForm() { const draft = crm2OportunidadesState.draft; const matches = crm2OportunidadesState.duplicateMatches; return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-lead-form-title"><div class="admin-panel-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · LEAD PROVISÓRIO</span><h3 id="crm2-lead-form-title">Novo lead</h3><p class="crm2-opp-subtitle">Faça a busca inicial para evitar duplicidades antes de cadastrar.</p></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Voltar</button></div><form class="crm2-opp-duplicate-check" onsubmit="crm2OportunidadesCheckDuplicate(event)"><label><span>Buscar cadastro existente</span><input class="config-input" name="duplicateQuery" value="${attrOpp(crm2OportunidadesState.duplicateQuery)}" placeholder="CPF, CNPJ, nome, razão social ou e-mail"></label><button class="secondary-btn" type="submit">Verificar duplicidade</button></form>${matches.length ? `<div class="crm2-opp-duplicate-alert" role="alert"><strong>Possíveis registros encontrados</strong><span>Revise antes de criar um lead provisório.</span><div>${matches.map((match) => `<article><strong>${escapeOpp(match.nome || match.razaoSocial)}</strong><small>${escapeOpp(match.origemRegistro)} · ${escapeOpp(match.cpf || match.cnpj || match.email || '')}</small><button class="secondary-btn" type="button" onclick="crm2OportunidadesOpenExisting('${attrOpp(match.id)}','${attrOpp(match.origemRegistro)}')">Abrir registro</button></article>`).join('')}</div>${!crm2OportunidadesState.allowDuplicate ? '<button class="secondary-btn" type="button" onclick="crm2OportunidadesAllowDuplicate()">Continuar como lead provisório</button>' : '<small>Continuação como lead provisório confirmada.</small>'}</div>` : crm2OportunidadesState.duplicateChecked ? '<p class="crm2-opp-duplicate-ok" role="status">Nenhuma duplicidade encontrada na base mockada.</p>' : ''}<form class="crm2-opp-form" onsubmit="crm2OportunidadesSaveLead(event)"><div class="crm2-opp-form-grid">${oppField({ label: 'Tipo', name: 'tipo', value: draft.tipo || 'provisorio', type: 'select', options: ['PF', 'PJ', 'provisorio'], required: true })}${oppField({ label: 'Nome ou razão social', name: 'nome', value: draft.nome || draft.razaoSocial, required: true })}${oppField({ label: 'CPF/CNPJ', name: 'documento', value: draft.cpf || draft.cnpj })}${oppField({ label: 'E-mail', name: 'email', value: draft.email, type: 'email' })}${oppField({ label: 'Telefone', name: 'telefone', value: draft.telefone })}${oppField({ label: 'Origem', name: 'origem', value: draft.origem || 'Atendimento interno', type: 'select', options: OPPORTUNITY_SOURCES, required: true })}${oppField({ label: 'Responsável', name: 'responsavel', value: draft.responsavel || 'Ana Martins', required: true })}${oppField({ label: 'Observações', name: 'observacoes', value: draft.observacoes, type: 'textarea', wide: true })}</div><div class="crm2-opp-form-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Cancelar</button><button class="save-btn" type="submit" ${matches.length && !crm2OportunidadesState.allowDuplicate ? 'disabled' : ''}>Salvar lead provisório</button></div></form></section>`; }
function oppField({ label, name, value = '', type = 'text', options = [], required = false, wide = false }) { const error = crm2OportunidadesState.errors[name] || ''; const id = `crm2-opp-${name}`; const common = `id="${id}" class="config-input" name="${name}" ${required ? 'required' : ''} aria-invalid="${error ? 'true' : 'false'}"`; const normalizedOptions = options.map((item) => typeof item === 'string' ? { value: item, label: item } : item); const input = type === 'textarea' ? `<textarea ${common} rows="4">${escapeOpp(value)}</textarea>` : type === 'select' ? `<select ${common}><option value="">Selecione</option>${normalizedOptions.map((item) => `<option value="${attrOpp(item.value)}" ${String(item.value) === String(value) ? 'selected' : ''}>${escapeOpp(item.label)}</option>`).join('')}</select>` : `<input ${common} type="${type}" value="${attrOpp(value)}">`; return `<label class="${wide ? 'is-wide' : ''}"><span>${escapeOpp(label)}${required ? ' *' : ''}</span>${input}${error ? `<small class="crm2-field-error">${escapeOpp(error)}</small>` : ''}</label>`; }

function renderOppForm() { const draft = crm2OportunidadesState.draft; const editing = crm2OportunidadesState.formMode === 'edit'; const leadOptions = crm2OportunidadesState.leads.map((lead) => ({ value: lead.id, label: `${lead.id} · ${leadLabel(lead)}` })); const pfOptions = (window.crm2PfGetMockItems?.() || []).map((item) => ({ value: item.id, label: `${item.id} · ${item.nome}` })); const pjOptions = (window.crm2PjGetMockItems?.() || []).map((item) => ({ value: item.id, label: `${item.id} · ${item.razaoSocial}` })); return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-opp-form-title"><div class="admin-panel-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · OPORTUNIDADE</span><h3 id="crm2-opp-form-title">${editing ? 'Editar oportunidade' : 'Nova oportunidade'}</h3><p class="crm2-opp-subtitle">Itens e negociação permanecem em memória nesta fase.</p></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Voltar</button></div><form class="crm2-opp-form" onsubmit="crm2OportunidadesSave(event)"><div class="crm2-opp-form-grid">${oppField({ label: 'Título', name: 'titulo', value: draft.titulo, required: true, wide: true })}${oppField({ label: 'Lead relacionado', name: 'leadId', value: draft.leadId, type: 'select', options: leadOptions })}${oppField({ label: 'Pessoa física', name: 'pfId', value: draft.pfId, type: 'select', options: pfOptions })}${oppField({ label: 'Pessoa jurídica', name: 'pjId', value: draft.pjId, type: 'select', options: pjOptions })}${oppField({ label: 'Etapa', name: 'etapa', value: draft.etapa, type: 'select', options: OPPORTUNITY_STAGES, required: true })}${oppField({ label: 'Status', name: 'status', value: draft.status, type: 'select', options: OPPORTUNITY_STATUSES, required: true })}${oppField({ label: 'Responsável', name: 'responsavel', value: draft.responsavel, required: true })}${oppField({ label: 'Origem', name: 'origem', value: draft.origem, type: 'select', options: OPPORTUNITY_SOURCES, required: true })}${oppField({ label: 'Probabilidade (%)', name: 'probabilidade', value: draft.probabilidade, type: 'number' })}${oppField({ label: 'Previsão de fechamento', name: 'previsaoFechamento', value: draft.previsaoFechamento, type: 'date' })}${oppField({ label: 'Motivo de perda', name: 'motivoPerda', value: draft.motivoPerda, type: 'select', options: OPPORTUNITY_LOSS_REASONS })}${oppField({ label: 'Observações', name: 'observacoes', value: draft.observacoes, type: 'textarea', wide: true })}</div><div class="crm2-opp-items-header"><strong>Itens da oportunidade</strong><button class="secondary-btn" type="button" onclick="crm2OportunidadesAddItem()">+ Adicionar item</button></div><div class="crm2-opp-items">${(draft.itens || []).map((item, index) => `<article><label><span>Produto</span><select class="config-input" name="itemProduct-${index}"><option value="">Selecione</option>${OPPORTUNITY_PRODUCTS.map((product) => `<option value="${attrOpp(product)}" ${item.produto === product ? 'selected' : ''}>${escapeOpp(product)}</option>`).join('')}</select></label><label><span>Quantidade</span><input class="config-input" type="number" min="1" name="itemQuantity-${index}" value="${attrOpp(item.quantidade || 1)}"></label><label><span>Valor unitário</span><input class="config-input" name="itemValue-${index}" value="${attrOpp(item.valorUnitario || '')}" placeholder="0,00"></label>${(draft.itens || []).length > 1 ? `<button class="secondary-btn" type="button" onclick="crm2OportunidadesRemoveItem(${index})">Remover</button>` : ''}</article>`).join('')}</div><div class="crm2-opp-form-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Cancelar</button><button class="save-btn" type="submit">${editing ? 'Salvar alterações' : 'Salvar oportunidade'}</button></div></form></section>`; }

function renderOppDetail(opp) { const history = [...(opp.historico || [])].sort((a, b) => new Date(b.data) - new Date(a.data)); const lead = leadById(opp.leadId); const pf = relatedPfOpp(opp.pfId); const pj = relatedPjOpp(opp.pjId); const content = crm2OportunidadesState.detailTab === 'itens' ? `<div class="crm2-opp-detail-items">${(opp.itens || []).map((item) => `<article><strong>${escapeOpp(item.produto)}</strong><span>${item.quantidade} × ${moneyOpp(item.valorUnitario)}</span><small>Total: ${moneyOpp((Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.'))).toFixed(2).replace('.', ','))}</small></article>`).join('')}</div>` : crm2OportunidadesState.detailTab === 'timeline' ? `<div class="crm2-opp-timeline">${history.length ? history.map((event) => `<article><span class="crm2-opp-timeline-marker" aria-hidden="true"></span><div><header><strong>${escapeOpp(event.tipo || 'Evento')}</strong><small>${escapeOpp(dateTimeOpp(event.data))}</small></header><p>${escapeOpp(event.descricao || '')}</p><small>${escapeOpp(event.usuario || 'Sistema')} · ${escapeOpp(event.alteracoes || '')}</small></div></article>`).join('') : '<div class="crm2-pessoas-state is-compact"><strong>Nenhum evento.</strong><span>A timeline será preenchida pelas interações comerciais.</span></div>'}</div>` : `<div class="crm2-opp-detail-grid"><div><span>Título</span><strong>${escapeOpp(opp.titulo)}</strong></div><div><span>Etapa</span><strong>${stagePillOpp(opp.etapa)}</strong></div><div><span>Lead</span><strong>${escapeOpp(leadLabel(lead))}</strong><small>${escapeOpp(lead?.email || lead?.cpf || lead?.cnpj || 'Identificação provisória')}</small></div><div><span>PF/PJ relacionada</span><strong>${escapeOpp(pf?.nome || pj?.razaoSocial || 'Não vinculada')}</strong></div><div><span>Responsável</span><strong>${escapeOpp(opp.responsavel)}</strong></div><div><span>Valor estimado</span><strong>${moneyOpp(opp.valorEstimado || totalOpp(opp))}</strong></div><div><span>Previsão de fechamento</span><strong>${escapeOpp(dateOpp(opp.previsaoFechamento))}</strong></div><div><span>Status</span><strong>${stagePillOpp(opp.status)}</strong></div><div class="is-wide"><span>Observações</span><strong>${escapeOpp(opp.observacoes || 'Nenhuma observação registrada.')}</strong></div></div>`; return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-opp-detail-title"><div class="admin-panel-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · OPORTUNIDADE</span><h3 id="crm2-opp-detail-title">${escapeOpp(opp.numero)} · ${escapeOpp(opp.titulo)}</h3><p class="crm2-opp-subtitle">${escapeOpp(opportunityLabel(opp))} · atualizado em ${escapeOpp(dateTimeOpp(opp.atualizadoEm))}</p></div><div class="crm2-pessoas-header-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Voltar</button>${crm2OportunidadesState.canEdit ? `<button class="save-btn" type="button" onclick="crm2OportunidadesOpenEdit('${attrOpp(opp.id)}')">Editar</button>` : ''}</div></div><div class="crm2-opp-detail-summary"><article><span>Etapa</span><strong>${stagePillOpp(opp.etapa)}</strong></article><article><span>Valor</span><strong>${moneyOpp(opp.valorEstimado || totalOpp(opp))}</strong></article><article><span>Itens</span><strong>${(opp.itens || []).length}</strong></article><article><span>Probabilidade</span><strong>${escapeOpp(opp.probabilidade)}%</strong></article></div><div class="crm2-opp-detail-actions"><select class="config-input" aria-label="Alterar etapa" onchange="crm2OportunidadesChangeStage('${attrOpp(opp.id)}', this.value)">${OPPORTUNITY_STAGES.map((stage) => `<option value="${attrOpp(stage)}" ${opp.etapa === stage ? 'selected' : ''}>${escapeOpp(stage)}</option>`).join('')}</select><button class="secondary-btn" type="button" onclick="crm2OportunidadesNoticeConversion()">Conversão (Fase 10)</button></div><div class="crm2-opp-tabs" role="tablist" aria-label="Detalhes da oportunidade">${[['dados', 'Dados gerais'], ['itens', 'Itens'], ['timeline', 'Timeline comercial']].map(([id, label]) => `<button class="${crm2OportunidadesState.detailTab === id ? 'active' : ''}" type="button" role="tab" aria-selected="${crm2OportunidadesState.detailTab === id}" onclick="crm2OportunidadesSelectTab('${id}')">${label}</button>`).join('')}</div><div class="crm2-opp-detail-content">${content}</div></section>`; }

function renderOpp() { permissionsOpp(); const route = currentOppRoute(); if (!crm2OportunidadesState.canView) return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true"><div class="crm2-pessoas-state is-error" role="alert"><strong>Acesso não autorizado.</strong><span>É necessária a permissão Visualizar para acessar Oportunidades.</span><button class="secondary-btn" type="button" onclick="navegarParaCrm2Rota('200')">Voltar ao CRM 2.0</button></div></section>`; if (route.view === 'lead-new') { if (!crm2OportunidadesState.canCreate) return renderOppState(); if (crm2OportunidadesState.formMode !== 'lead') { crm2OportunidadesState.formMode = 'lead'; crm2OportunidadesState.draft = {}; } return renderLeadForm(); } if (route.view === 'opp-new' || route.view === 'opp-edit') { if (route.view === 'opp-new' && !crm2OportunidadesState.canCreate) return renderOppState(); if (route.view === 'opp-edit' && !crm2OportunidadesState.canEdit) return renderOppState(); const opp = opportunityById(route.id); if (route.view === 'opp-edit' && !opp) return renderOppState(); if (crm2OportunidadesState.formMode !== 'opportunity' || crm2OportunidadesState.detailId !== (opp?.id || '')) { crm2OportunidadesState.formMode = 'opportunity'; crm2OportunidadesState.detailId = opp?.id || ''; crm2OportunidadesState.draft = formDefaultsOpp(opp || {}); } return renderOppForm(); } if (route.view === 'opp-detail') { const opp = opportunityById(route.id); return opp ? renderOppDetail(opp) : renderOppState(); } resetOppForm(); return renderOppList(); }
function rerenderOpp() { if (currentOppRoute().active && document.querySelector('[data-crm2-oportunidades="true"]')) document.querySelector('[data-crm2-oportunidades="true"]').outerHTML = renderOpp(); }
function validateLeadOpp(values) { const errors = {}; if (!String(values.nome || '').trim()) errors.nome = 'Informe nome ou razão social.'; if (!String(values.origem || '').trim()) errors.origem = 'Informe a origem.'; if (!String(values.responsavel || '').trim()) errors.responsavel = 'Informe o responsável.'; return errors; }
function validateOpportunityOpp(values) { const errors = {}; if (!String(values.titulo || '').trim()) errors.titulo = 'Informe o título.'; if (!String(values.responsavel || '').trim()) errors.responsavel = 'Informe o responsável.'; if (values.etapa === 'Perdida' && !values.motivoPerda) errors.motivoPerda = 'Informe o motivo da perda.'; if (!values.itens?.length || values.itens.some((item) => !item.produto || Number(item.quantidade) < 1 || !String(item.valorUnitario).trim())) errors.itens = 'Preencha produto, quantidade e valor de todos os itens.'; return errors; }

Object.assign(window, {
  crm2OportunidadesRender: renderOpp,
  crm2OportunidadesMount() { const target = document.querySelector('[data-crm2-oportunidades="true"]'); if (target) target.outerHTML = renderOpp(); },
  navegarParaCrm2OportunidadesRota() { permissionsOpp(); if (crm2OportunidadesState.canView) navigateOpp(); },
  crm2OportunidadesOpenCreate() { if (!crm2OportunidadesState.canCreate) return; crm2OportunidadesState.formMode = 'opportunity'; crm2OportunidadesState.detailId = ''; crm2OportunidadesState.draft = formDefaultsOpp(); navigateOpp('oportunidade/novo'); },
  crm2OportunidadesOpenLeadCreate() { if (!crm2OportunidadesState.canCreate) return; crm2OportunidadesState.formMode = 'lead'; crm2OportunidadesState.draft = {}; crm2OportunidadesState.duplicateQuery = ''; crm2OportunidadesState.duplicateMatches = []; crm2OportunidadesState.duplicateChecked = false; crm2OportunidadesState.allowDuplicate = false; navigateOpp('lead/novo'); },
  crm2OportunidadesOpenDetail(id) { if (!opportunityById(id)) return; crm2OportunidadesState.detailId = id; crm2OportunidadesState.detailTab = 'dados'; navigateOpp(`oportunidade/${id}`); },
  crm2OportunidadesOpenEdit(id) { if (!crm2OportunidadesState.canEdit || !opportunityById(id)) return; crm2OportunidadesState.formMode = 'opportunity'; crm2OportunidadesState.detailId = id; crm2OportunidadesState.draft = formDefaultsOpp(opportunityById(id)); navigateOpp(`oportunidade/${id}/editar`); },
  crm2OportunidadesBack() { resetOppForm(); navigateOpp(); },
  crm2OportunidadesSetSection(section) { crm2OportunidadesState.section = section === 'leads' ? 'leads' : 'opportunities'; rerenderOpp(); },
  crm2OportunidadesSetView(view) { crm2OportunidadesState.viewMode = view === 'kanban' ? 'kanban' : 'table'; rerenderOpp(); },
  crm2OportunidadesSetPage(page) { crm2OportunidadesState.page = Math.max(1, Number(page) || 1); rerenderOpp(); },
  crm2OportunidadesSetState(state) { crm2OportunidadesState.listState = ['normal', 'loading', 'error', 'empty'].includes(state) ? state : 'normal'; rerenderOpp(); },
  crm2OportunidadesApplyFilters(event) { event?.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); Object.assign(crm2OportunidadesState, { search: String(values.search || '').trim(), stageFilter: String(values.stage || ''), statusFilter: String(values.status || ''), responsibleFilter: String(values.responsible || ''), sourceFilter: String(values.source || ''), lossReasonFilter: String(values.lossReason || ''), dateFrom: String(values.dateFrom || ''), dateTo: String(values.dateTo || ''), page: 1 }); rerenderOpp(); },
  crm2OportunidadesClearFilters() { Object.assign(crm2OportunidadesState, { search: '', stageFilter: '', statusFilter: '', responsibleFilter: '', sourceFilter: '', lossReasonFilter: '', dateFrom: '', dateTo: '', page: 1 }); rerenderOpp(); },
  crm2OportunidadesCheckDuplicate(event) { event?.preventDefault(); const query = String(new FormData(event.currentTarget).get('duplicateQuery') || '').trim(); crm2OportunidadesState.duplicateQuery = query; crm2OportunidadesState.duplicateMatches = duplicateMatchesOpp(query); crm2OportunidadesState.duplicateChecked = true; crm2OportunidadesState.allowDuplicate = false; rerenderOpp(); },
  crm2OportunidadesAllowDuplicate() { crm2OportunidadesState.allowDuplicate = true; rerenderOpp(); },
  crm2OportunidadesOpenExisting(id, source) { if (source === 'Pessoa Física') window.crm2PfOpenDetail?.(id); else if (source === 'Pessoa Jurídica') window.crm2PjOpenDetail?.(id); else { const lead = leadById(id); if (lead) { crm2OportunidadesState.section = 'leads'; crm2OportunidadesBack(); } } },
  crm2OportunidadesSaveLead(event) { event?.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const errors = validateLeadOpp(values); crm2OportunidadesState.errors = errors; if (Object.keys(errors).length || (crm2OportunidadesState.duplicateMatches.length && !crm2OportunidadesState.allowDuplicate)) { rerenderOpp(); return; } const id = `lead-${String(crm2OportunidadesState.leads.length + 1).padStart(3, '0')}`; const lead = { id, tipo: values.tipo || 'provisorio', nome: values.tipo === 'PJ' ? '' : values.nome, razaoSocial: values.tipo === 'PJ' ? values.nome : '', cpf: values.tipo === 'PF' ? digitsOpp(values.documento) : '', cnpj: values.tipo === 'PJ' ? digitsOpp(values.documento) : '', email: values.email || '', telefone: values.telefone || '', origem: values.origem, responsavel: values.responsavel, status: 'Novo', criadoEm: new Date().toISOString(), atualizadoEm: new Date().toISOString(), observacoes: values.observacoes || '' }; crm2OportunidadesState.leads.unshift(lead); crm2OportunidadesState.message = 'Lead provisório criado no estado mockado.'; resetOppForm(); navigateOpp(); },
  crm2OportunidadesAddItem() { crm2OportunidadesState.draft.itens = [...(crm2OportunidadesState.draft.itens || []), { id: `item-${Date.now()}`, produto: '', quantidade: 1, valorUnitario: '' }]; rerenderOpp(); },
  crm2OportunidadesRemoveItem(index) { crm2OportunidadesState.draft.itens.splice(Number(index), 1); rerenderOpp(); },
  crm2OportunidadesSave(event) { event?.preventDefault(); const formValues = Object.fromEntries(new FormData(event.currentTarget).entries()); const items = Object.keys(formValues).filter((key) => key.startsWith('itemProduct-')).map((key) => { const index = key.split('-')[1]; return { id: crm2OportunidadesState.draft.itens?.[index]?.id || `item-${Date.now()}-${index}`, produto: formValues[`itemProduct-${index}`], quantidade: Number(formValues[`itemQuantity-${index}`] || 0), valorUnitario: formValues[`itemValue-${index}`] || '' }; }); const values = { ...formValues, itens: items }; crm2OportunidadesState.draft = values; const errors = validateOpportunityOpp(values); crm2OportunidadesState.errors = errors; if (Object.keys(errors).length) { rerenderOpp(); return; } const now = new Date().toISOString(); if (crm2OportunidadesState.formMode === 'opportunity' && crm2OportunidadesState.detailId) { const opp = opportunityById(crm2OportunidadesState.detailId); const previousStage = opp.etapa; Object.assign(opp, values, { atualizadoEm: now, valorEstimado: values.itens.reduce((total, item) => total + Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.')), 0).toFixed(2).replace('.', ',') }); opp.historico = [...(opp.historico || []), { data: now, tipo: previousStage !== values.etapa ? 'Etapa' : 'Edição', usuario: values.responsavel, descricao: 'Oportunidade atualizada no estado mockado.', alteracoes: previousStage !== values.etapa ? `Etapa: ${previousStage} → ${values.etapa}` : 'Dados comerciais revisados.' }]; resetOppForm(); navigateOpp(`oportunidade/${opp.id}`); return; } const id = `opp-${String(crm2OportunidadesState.opportunities.length + 1).padStart(3, '0')}`; const opp = { ...values, id, numero: `OPP-${String(crm2OportunidadesState.opportunities.length + 1).padStart(3, '0')}`, status: values.etapa === 'Perdida' ? 'Perdida' : values.status || 'Aberta', valorEstimado: values.itens.reduce((total, item) => total + Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.')), 0).toFixed(2).replace('.', ','), criadoEm: now, atualizadoEm: now, historico: [{ data: now, tipo: 'Criação', usuario: values.responsavel, descricao: 'Oportunidade criada no estado mockado.', alteracoes: `Etapa: — → ${values.etapa}` }] }; crm2OportunidadesState.opportunities.unshift(opp); resetOppForm(); navigateOpp(`oportunidade/${opp.id}`); },
  crm2OportunidadesSelectTab(tab) { if (['dados', 'itens', 'timeline'].includes(tab)) { crm2OportunidadesState.detailTab = tab; rerenderOpp(); } },
  crm2OportunidadesChangeStage(id, stage) { if (!crm2OportunidadesState.canEdit) return; const opp = opportunityById(id); if (!opp || opp.etapa === stage) return; if (stage === 'Perdida') { const reason = window.prompt('Informe o motivo da perda:'); if (!reason) { rerenderOpp(); return; } opp.motivoPerda = reason; opp.status = 'Perdida'; } else if (stage === 'Ganha') opp.status = 'Ganha'; else if (opp.status !== 'Arquivada') opp.status = 'Aberta'; const previous = opp.etapa; opp.etapa = stage; opp.atualizadoEm = new Date().toISOString(); opp.historico = [...(opp.historico || []), { data: opp.atualizadoEm, tipo: stage === 'Perdida' ? 'Perda' : 'Etapa', usuario: opp.responsavel, descricao: `Etapa alterada para ${stage}.`, alteracoes: `Etapa: ${previous} → ${stage}` }]; crm2OportunidadesState.detailTab = 'timeline'; rerenderOpp(); },
  crm2OportunidadesNoticeConversion() { crm2OportunidadesState.message = 'A conversão será implementada na Fase 10. Nenhum cadastro oficial foi alterado.'; rerenderOpp(); }
});

observarContextoAcessoHub(() => { permissionsOpp(); if (currentOppRoute().active) window.crm2OportunidadesMount?.(); });
permissionsOpp();

function conversionItemsAvailableOpp(opp) { return (opp?.itens || []).filter((item) => !item.conversaoEm && !(item.pedidoIds || []).length); }
function conversionRecordOpp(type, id) { return (type === 'pf' ? (window.crm2PfGetMockItems?.() || []) : (window.crm2PjGetMockItems?.() || [])).find((item) => item.id === id) || null; }
function conversionRenderOpp() {
  const opp = opportunityById(crm2OportunidadesState.detailId);
  const state = crm2OportunidadesState.conversion;
  if (!opp || !state.open) return '';
  if (state.result) return `<div class="crm2-opp-conversion-backdrop"><section class="crm2-opp-conversion-modal" role="dialog" aria-modal="true" aria-labelledby="crm2-conversion-success-title"><div class="crm2-opp-conversion-header"><div><span class="ar-crm-phase1-kicker">CONVERSAO CONCLUIDA</span><h3 id="crm2-conversion-success-title">${escapeOpp(state.result.mode === 'total' ? 'Conversao total realizada' : 'Conversao parcial realizada')}</h3></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesCloseConversion()">Fechar</button></div><div class="crm2-opp-conversion-success" role="status"><strong>${state.result.orders.length} pedido(s) criado(s) no estado mockado.</strong><span>${escapeOpp(state.result.pfLabel)}${state.result.pjLabel ? ` · ${escapeOpp(state.result.pjLabel)}` : ''}</span></div><div class="crm2-opp-conversion-result-grid"><article><span>Itens convertidos</span><strong>${state.result.itemCount}</strong></article><article><span>Vinculo</span><strong>${escapeOpp(state.result.linkLabel)}</strong></article><article><span>Status comercial</span><strong>${escapeOpp(state.result.statusLabel)}</strong></article></div><div class="crm2-opp-conversion-orders"><strong>Pedidos gerados</strong>${state.result.orders.map((order) => `<article><div><strong>${escapeOpp(order.numero)}</strong><span>${escapeOpp(order.produto)}</span></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesOpenGeneratedOrder('${attrOpp(order.id)}')">Abrir pedido</button></article>`).join('')}</div><div class="crm2-opp-conversion-actions"><button class="save-btn" type="button" onclick="crm2OportunidadesCloseConversion()">Voltar ao detalhe</button></div></section></div>`;
  const items = conversionItemsAvailableOpp(opp);
  const stateErrors = Object.values(state.errors || {});
  const pfItems = window.crm2PfGetMockItems?.() || [];
  const pjItems = window.crm2PjGetMockItems?.() || [];
  return `<div class="crm2-opp-conversion-backdrop"><section class="crm2-opp-conversion-modal" role="dialog" aria-modal="true" aria-labelledby="crm2-conversion-title"><div class="crm2-opp-conversion-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · CONVERSAO</span><h3 id="crm2-conversion-title">Converter ${escapeOpp(opp.numero)}</h3><p>${escapeOpp(opp.titulo)}</p></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesCloseConversion()">Fechar</button></div>${stateErrors.length ? `<div class="crm2-opp-conversion-errors" role="alert"><strong>Revise antes de confirmar:</strong><ul>${stateErrors.map((error) => `<li>${escapeOpp(error)}</li>`).join('')}</ul></div>` : ''}<div class="crm2-opp-conversion-summary"><span>Lead/cliente</span><strong>${escapeOpp(opportunityLabel(opp))}</strong><small>${escapeOpp(opp.responsavel)} · ${moneyOpp(opp.valorEstimado || totalOpp(opp))}</small></div><div class="crm2-opp-conversion-mode" role="radiogroup" aria-label="Tipo de conversao"><label><input type="radio" name="conversionMode" value="total" ${state.mode === 'total' ? 'checked' : ''} onchange="crm2OportunidadesSetConversionField('mode', this.value)"><span>Conversao total</span><small>Seleciona todos os itens pendentes.</small></label><label><input type="radio" name="conversionMode" value="partial" ${state.mode === 'partial' ? 'checked' : ''} onchange="crm2OportunidadesSetConversionField('mode', this.value)"><span>Conversao parcial</span><small>Escolha somente os itens gerados agora.</small></label></div><div class="crm2-opp-conversion-section"><div class="crm2-opp-items-header"><strong>Itens da conversao</strong><span>${state.selectedItemIds.length} de ${items.length} selecionado(s)</span></div><div class="crm2-opp-conversion-items">${items.length ? items.map((item) => `<label class="${state.selectedItemIds.includes(item.id) ? 'is-selected' : ''}"><input type="checkbox" value="${attrOpp(item.id)}" ${state.selectedItemIds.includes(item.id) ? 'checked' : ''} onchange="crm2OportunidadesToggleConversionItem(this.value)"><span><strong>${escapeOpp(item.produto)}</strong><small>${item.quantidade} × ${moneyOpp(item.valorUnitario)}</small></span></label>`).join('') : '<div class="crm2-pessoas-state is-compact"><strong>Todos os itens ja foram convertidos.</strong><span>Nenhum pedido novo sera gerado.</span></div>'}</div></div><div class="crm2-opp-conversion-section"><div class="crm2-opp-conversion-fields"><label><span>Pessoa Fisica *</span><select class="config-input" onchange="crm2OportunidadesSetConversionField('pfId', this.value)"><option value="">Selecione uma PF existente</option>${pfItems.map((item) => `<option value="${attrOpp(item.id)}" ${state.pfId === item.id ? 'selected' : ''}>${escapeOpp(item.nome)} · ${escapeOpp(item.cpf)}</option>`).join('')}</select></label><label><span>Pessoa Juridica</span><select class="config-input" onchange="crm2OportunidadesSetConversionField('pjId', this.value)"><option value="">Sem PJ vinculada</option>${pjItems.map((item) => `<option value="${attrOpp(item.id)}" ${state.pjId === item.id ? 'selected' : ''}>${escapeOpp(item.razaoSocial)} · ${escapeOpp(item.cnpj)}</option>`).join('')}</select></label><label><span>Vinculo PF/PJ</span><select class="config-input" onchange="crm2OportunidadesSetConversionField('vinculoTipo', this.value)"><option value="Nenhum">Nao criar vinculo</option>${['Titular', 'Representante legal', 'Contador', 'Outros'].map((type) => `<option value="${attrOpp(type)}" ${state.vinculoTipo === type ? 'selected' : ''}>${escapeOpp(type)}</option>`).join('')}</select></label><label><span>Responsavel pela conversao</span><input class="config-input" value="${attrOpp(state.responsavel)}" oninput="crm2OportunidadesSetConversionField('responsavel', this.value)"></label><label class="is-wide"><span>Observacoes</span><textarea class="config-input" rows="3" oninput="crm2OportunidadesSetConversionField('observacoes', this.value)" placeholder="Observacao registrada no historico">${escapeOpp(state.observacoes)}</textarea></label></div></div><div class="crm2-opp-conversion-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesCloseConversion()">Cancelar</button><button class="save-btn" type="button" onclick="crm2OportunidadesConfirmConversion()" ${items.length ? '' : 'disabled'}>Confirmar conversao</button></div></section></div>`;
}
function mountConversionOpp() { const host = document.querySelector('[data-crm2-oportunidades="true"]'); if (!host) return; host.querySelector('.crm2-opp-conversion-backdrop')?.remove(); if (crm2OportunidadesState.conversion.open) host.insertAdjacentHTML('beforeend', conversionRenderOpp()); }
function openConversionOpp(id = '') { permissionsOpp(); const opp = opportunityById(id || crm2OportunidadesState.detailId); if (!opp || !crm2OportunidadesState.canEdit || ['Perdida', 'Ganha'].includes(opp.etapa) && opp.conversaoStatus === 'Total') return; const items = conversionItemsAvailableOpp(opp); crm2OportunidadesState.detailId = opp.id; crm2OportunidadesState.conversion = { open: true, mode: 'total', selectedItemIds: items.map((item) => item.id), pfId: opp.pfId || '', pjId: opp.pjId || '', vinculoTipo: opp.pjId ? 'Representante legal' : 'Representante legal', responsavel: opp.responsavel || 'Ana Martins', observacoes: '', errors: {}, result: null }; rerenderOpp(); window.setTimeout(mountConversionOpp, 0); }
function closeConversionOpp() { crm2OportunidadesState.conversion = { open: false, mode: 'total', selectedItemIds: [], pfId: '', pjId: '', vinculoTipo: 'Representante legal', responsavel: 'Ana Martins', observacoes: '', errors: {}, result: null }; document.querySelector('.crm2-opp-conversion-backdrop')?.remove(); }
function setConversionFieldOpp(field, value) { if (!['mode', 'pfId', 'pjId', 'vinculoTipo', 'responsavel', 'observacoes'].includes(field)) return; crm2OportunidadesState.conversion[field] = String(value || ''); if (field === 'mode' && value === 'total') { const opp = conversionOpportunityOpp(); crm2OportunidadesState.conversion.selectedItemIds = conversionItemsAvailableOpp(opp).map((item) => item.id); } if (field === 'mode' && value === 'partial' && !crm2OportunidadesState.conversion.selectedItemIds.length) { const opp = conversionOpportunityOpp(); crm2OportunidadesState.conversion.selectedItemIds = conversionItemsAvailableOpp(opp).slice(0, 1).map((item) => item.id); } mountConversionOpp(); }
function toggleConversionItemOpp(id) { const ids = crm2OportunidadesState.conversion.selectedItemIds; crm2OportunidadesState.conversion.selectedItemIds = ids.includes(id) ? ids.filter((itemId) => itemId !== id) : [...ids, id]; crm2OportunidadesState.conversion.mode = 'partial'; mountConversionOpp(); }
function executeConversionOpp() {
  permissionsOpp();
  const opp = conversionOpportunityOpp();
  const state = crm2OportunidadesState.conversion;
  const errors = {};
  if (!opp) errors.record = 'Oportunidade nao encontrada.';
  if (!crm2OportunidadesState.canEdit) errors.permission = 'Voce nao possui permissao para confirmar a conversao.';
  if (opp && ['Perdida'].includes(opp.etapa)) errors.stage = 'Oportunidades perdidas nao podem ser convertidas.';
  const available = conversionItemsAvailableOpp(opp);
  const selected = available.filter((item) => state.selectedItemIds.includes(item.id));
  if (!selected.length) errors.items = 'Selecione ao menos um item para converter.';
  const pf = conversionRecordOpp('pf', state.pfId) || (opp?.pfId ? relatedPfOpp(opp.pfId) : null);
  const pj = conversionRecordOpp('pj', state.pjId) || (opp?.pjId ? relatedPjOpp(opp.pjId) : null);
  const lead = conversionLeadOpp(opp);
  const hasLeadPf = lead?.tipo === 'PF' && String(lead.cpf || '').replace(/\D/g, '').length === 11;
  const hasLeadPj = lead?.tipo === 'PJ' && String(lead.cnpj || '').replace(/\D/g, '').length === 14;
  if (!pf && !hasLeadPf) errors.pf = 'Selecione uma PF existente ou vincule um lead PF com CPF valido.';
  if (!pj && hasLeadPj && typeof window.crm2PjCreateMockFromConversion !== 'function') errors.pj = 'A criacao mockada de PJ nao esta disponivel.';
  if (pj && state.vinculoTipo !== 'Nenhum' && typeof window.crm2VinculosCreateMockFromConversion !== 'function') errors.link = 'A criacao mockada de vinculo nao esta disponivel.';
  if (typeof window.crm2PedidosCreateMockFromConversion !== 'function') errors.orders = 'A criacao mockada de pedidos nao esta disponivel.';
  if (Object.keys(errors).length) { state.errors = errors; mountConversionOpp(); return; }
  const now = new Date().toISOString();
  const resolvedPf = pf || window.crm2PfCreateMockFromConversion({ nome: lead.nome, cpf: lead.cpf, email: lead.email, telefone: lead.telefone, usuario: state.responsavel });
  const resolvedPj = pj || (hasLeadPj ? window.crm2PjCreateMockFromConversion({ razaoSocial: lead.razaoSocial || lead.nome, cnpj: lead.cnpj, observacoes: state.observacoes, usuario: state.responsavel }) : null);
  if (!resolvedPf || (hasLeadPj && !resolvedPj)) { state.errors = { records: 'Nao foi possivel criar os registros mockados de PF/PJ.' }; mountConversionOpp(); return; }
  let link = null;
  if (resolvedPj && state.vinculoTipo !== 'Nenhum') link = window.crm2VinculosCreateMockFromConversion({ pfNome: resolvedPf.nome, pfCpf: resolvedPf.cpf, pjRazaoSocial: resolvedPj.razaoSocial, pjCnpj: resolvedPj.cnpj, tipo: state.vinculoTipo, observacoes: state.observacoes, usuario: state.responsavel });
  const orders = selected.map((item) => window.crm2PedidosCreateMockFromConversion({ pfNome: resolvedPf.nome, pfCpf: resolvedPf.cpf, pjRazaoSocial: resolvedPj?.razaoSocial || '', pjCnpj: resolvedPj?.cnpj || '', produto: item.produto, valor: (Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.'))).toFixed(2).replace('.', ','), responsavel: state.responsavel, oportunidadeId: opp.id, oportunidadeNumero: opp.numero }));
  if (orders.some((order) => !order)) { state.errors = { orders: 'Nao foi possivel gerar todos os pedidos mockados.' }; mountConversionOpp(); return; }
  const pedidoCards = orders.map((order) => ({ numero: order.numero, produto: order.produto, status: order.status, vencimento: order.vencimento }));
  window.crm2PfApplyConversionMock?.(resolvedPf.id, { pedidos: pedidoCards, vinculos: link && !link.reused ? [link] : [], observacoes: state.observacoes, usuario: state.responsavel, descricao: `Conversao da oportunidade ${opp.numero}.` });
  if (resolvedPj) window.crm2PjApplyConversionMock?.(resolvedPj.id, { pedidos: pedidoCards, vinculos: link && !link.reused ? [link] : [], observacoes: state.observacoes });
  selected.forEach((item) => { item.conversaoEm = now; item.pedidoIds = orders.map((order) => order.id); item.statusConversao = 'Convertido'; });
  const total = selected.length === available.length;
  opp.conversaoStatus = total ? 'Total' : 'Parcial';
  opp.status = total ? 'Ganha' : 'Aberta';
  if (total) opp.etapa = 'Ganha';
  opp.atualizadoEm = now;
  const conversionRecord = { data: now, usuario: state.responsavel, tipo: total ? 'Conversao total' : 'Conversao parcial', itens: selected.map((item) => item.id), pedidos: orders.map((order) => order.id), pfId: resolvedPf.id, pjId: resolvedPj?.id || '', vinculoId: link?.id || '', observacoes: state.observacoes };
  opp.conversoes = [...(opp.conversoes || []), conversionRecord];
  opp.historico = [...(opp.historico || []), { data: now, usuario: state.responsavel, tipo: total ? 'Conversao total' : 'Conversao parcial', descricao: `${total ? 'Conversao total' : 'Conversao parcial'} concluida no estado mockado.`, alteracoes: `Itens: ${selected.length} · Pedidos: ${orders.length}${link ? ` · Vinculo: ${link.tipo}` : ''}` }];
  state.errors = {};
  state.result = { mode: total ? 'total' : 'partial', itemCount: selected.length, orders, pfLabel: resolvedPf.nome, pjLabel: resolvedPj?.razaoSocial || '', linkLabel: link ? (link.reused ? `${link.tipo} (reutilizado)` : `${link.tipo} (criado)`) : 'Nenhum', statusLabel: total ? 'Ganha / convertida' : 'Aberta / parcial' };
  crm2OportunidadesState.message = 'Conversao concluida no estado mockado. Historico, pedidos e vinculos foram preservados.';
  rerenderOpp(); window.setTimeout(mountConversionOpp, 0);
}
Object.assign(window, {
  crm2OportunidadesNoticeConversion: openConversionOpp,
  crm2OportunidadesOpenConversion: openConversionOpp,
  crm2OportunidadesCloseConversion: closeConversionOpp,
  crm2OportunidadesSetConversionField: setConversionFieldOpp,
  crm2OportunidadesToggleConversionItem: toggleConversionItemOpp,
  crm2OportunidadesConfirmConversion: executeConversionOpp,
  crm2OportunidadesOpenGeneratedOrder(id) { if (id) window.crm2PedidosOpenDetail?.(id); }
});
